static int dvb_dmx_swfilter_section_copy_dump ( struct dvb_demux_feed * feed , const u8 * buf , u8 len ) { struct dvb_demux * demux = feed -> demux ; struct dmx_section_feed * sec = & feed -> feed . sec ; u16 limit , seclen , n ; if ( sec -> tsfeedp + len > DMX_MAX_SECFEED_SIZE ) { dprintk ( "dvb_demux.c section buffer full loss: %d/%d\n" , sec -> tsfeedp + len - DMX_MAX_SECFEED_SIZE , DMX_MAX_SECFEED_SIZE ) ; len = DMX_MAX_SECFEED_SIZE - sec -> tsfeedp ; } if ( len <= 0 ) { return 0 ; } demux -> memcopy ( feed , sec -> secbuf_base + sec -> tsfeedp , buf , len ) ; sec -> tsfeedp += len ; limit = sec -> tsfeedp ; if ( limit > DMX_MAX_SECFEED_SIZE ) { return - 1 ; } sec -> secbuf = sec -> secbuf_base + sec -> secbufp ; for ( n = 0 ; sec -> secbufp + 2 < limit ; n ++ ) { seclen = section_length ( sec -> secbuf ) ; if ( seclen <= 0 || seclen > DMX_MAX_SECTION_SIZE || seclen + sec -> secbufp > limit ) { return 0 ; } sec -> seclen = seclen ; sec -> crc_val = ~ 0 ; if ( feed -> pusi_seen ) { dvb_dmx_swfilter_section_feed ( feed ) ; } else { dprintk ( "dvb_demux.c pusi not seen, discarding section data\n" ) ; } sec -> secbufp += seclen ; sec -> secbuf += seclen ; } return 0 ; } 